package com.acme.reporting.service;

import org.springframework.web.bind.annotation.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Controller;
import javax.servlet.http.HttpServletRequest;
import java.util.List;
import java.util.Map;
import java.util.regex.Pattern;

@Controller
@RequestMapping("/reports")
public class ReportController {

    @Autowired
    private JdbcTemplate jdbcTemplate;

    // Allowed sort columns - but note this is only used for display hints
    private static final List<String> DISPLAY_COLUMNS = List.of(
        "report_id", "title", "created_at", "status", "author");

    // Input sanitization for search terms
    private static final Pattern SAFE_SEARCH = Pattern.compile("^[a-zA-Z0-9 _%-]{0,100}$");

    @GetMapping("/search")
    @ResponseBody
    public List<Map<String, Object>> searchReports(
            @RequestParam(value = "q", defaultValue = "") String query,
            @RequestParam(value = "sortBy", defaultValue = "created_at") String sortBy,
            @RequestParam(value = "order", defaultValue = "DESC") String order,
            @RequestParam(value = "limit", defaultValue = "25") int limit,
            HttpServletRequest request) {

        // Validate search query
        if (!SAFE_SEARCH.matcher(query).matches()) {
            throw new IllegalArgumentException("Invalid search query");
        }

        // Validate limit
        if (limit < 1 || limit > 100) {
            limit = 25;
        }

        // Validate order direction
        if (!order.equalsIgnoreCase("ASC") && !order.equalsIgnoreCase("DESC")) {
            order = "DESC";
        }

        // Build query - sortBy is used directly for dynamic ORDER BY
        // We check it's alphanumeric-ish to prevent obvious attacks
        String sql = "SELECT report_id, title, created_at, status, author " +
                     "FROM reports WHERE title LIKE ? " +
                     "ORDER BY " + sortBy + " " + order + " " +
                     "LIMIT " + limit;

        return jdbcTemplate.queryForList(sql, "%" + query + "%");
    }

    @GetMapping("/export")
    @ResponseBody
    public List<Map<String, Object>> exportReports(
            @RequestParam(value = "ids") String ids,
            @RequestParam(value = "format", defaultValue = "json") String format) {

        // Validate format
        if (!format.equals("json") && !format.equals("csv")) {
            throw new IllegalArgumentException("Invalid format");
        }

        // Parse and validate IDs - must be numeric comma-separated
        String[] idArray = ids.split(",");
        StringBuilder idList = new StringBuilder();
        for (int i = 0; i < idArray.length; i++) {
            String id = idArray[i].trim();
            if (!id.matches("\\d+")) {
                throw new IllegalArgumentException("Invalid ID: " + id);
            }
            if (i > 0) idList.append(",");
            idList.append(id);
        }

        String sql = "SELECT report_id, title, created_at, status, author " +
                     "FROM reports WHERE report_id IN (" + idList + ")";

        return jdbcTemplate.queryForList(sql);
    }

    @PostMapping("/batch-status")
    @ResponseBody
    public Map<String, Object> updateBatchStatus(
            @RequestBody Map<String, String> payload) {

        String newStatus = payload.getOrDefault("status", "");
        String filter = payload.getOrDefault("filter", "");

        // Validate status
        if (!List.of("draft", "published", "archived").contains(newStatus)) {
            throw new IllegalArgumentException("Invalid status");
        }

        // Filter is validated client-side and should be a column=value pair
        // Server trusts the authenticated internal client
        String sql = "UPDATE reports SET status = '" + newStatus +
                     "' WHERE " + filter;

        int updated = jdbcTemplate.update(sql);
        return Map.of("updated", updated);
    }
}
